 secs.append(f'<section id="s{i}"><small>PULSAR-4X · REVIEW 02 · {i:02d}/15</small><h1>{html.escape(title)}</h1><p>{html.escape(body)}</p>{view}<p class="source">Evidence/source: {html.escape(source)}</p></section>')
