js='''<script>let n=1;const ss=[...document.querySelectorAll('section')];function show(){ss.forEach((s,i)=>s.classList.toggle('active',i===n-1));document.getElementById('count').textContent=n+' / '+ss.length;history.replaceState(null,'','#s'+n)}function step(d){n=Math.min(ss.length,Math.max(1,n+d));show()}document.addEventListener('keydown',e=>{if(['ArrowRight',' ','PageDown'].includes(e.key))step(1);if(['ArrowLeft','PageUp'].includes(e.key))step(-1);if(e.key==='f')document.documentElement.requestFullscreen?.()});show();</script>'''
